import React, { HTMLAttributes, useState, useRef, useEffect, ComponentType } from 'react';
import classNames from 'classnames';
import { Dropdown } from '@teambit/design.inputs.dropdown';
import type { Position } from '@teambit/design.inputs.dropdown';
import { MenuItem } from '@teambit/design.inputs.selectors.menu-item';
import type { LinkProps } from '@teambit/base-react.navigation.link';
import { TabLine } from './tab-line';
import type { BorderPosition } from './tab-line';
import { TabFolder } from './tab-folder';
import { TabInner } from './tab-inner';

import styles from './responsive-navbar.module.scss';

export type Tab = {
  component: ComponentType<TabProps>;
  tabProps?: Omit<TabProps, 'isInMenu'>;
} & HTMLAttributes<HTMLDivElement>;

export type TabProps = {
  /**
   * to indicate when a tab is collapsed to the dropdown.
   */
  isInMenu: boolean;
  menuItemProps?: LinkProps & { displayName?: string };
} & HTMLAttributes<HTMLElement>;

export type ResponsiveNavbarProps = {
  /**
   * The tab that should be open on initial render.
   */
  defaultActiveIndex?: number;
  /**
   * A className to pass to nav container.
   */
  navClassName?: string;
  /**
   * A className to pass to the moving tab.
   */
  tabClassName?: string;
  /**
   * A className to pass to the secondary nav, i.e dropdown
   */
  secondaryNavClassName?: string;
  /**
   * Tab line border position can be top or bottom.
   */
  borderPosition?: BorderPosition;
  /**
   * An array of contents to render tab title and their content.
   */
  tabs: Tab[];
  dropdownPosition?: Position;
  onSelect?: (activeIndex: number) => void;
  /**
   * Styling options.
   */
  priority?: 'line' | 'folder' | 'inner' | 'none';
  alwaysShowActiveTab?: boolean;
} & HTMLAttributes<HTMLDivElement>;

export const ResponsiveNavbar = React.memo(_ResponsiveNavbar);

export function _ResponsiveNavbar({
  defaultActiveIndex = 0,
  onSelect,
  navClassName,
  tabClassName,
  secondaryNavClassName,
  borderPosition = 'bottom',
  tabs,
  dropdownPosition = 'bottom-end',
  priority = 'line',
  alwaysShowActiveTab = false,
  children, 
  ...rest
}: ResponsiveNavbarProps) {
  const [tabIndex, setTabIndex] = useState(defaultActiveIndex);
  const [selectedTab, setSelectedTab] = useState<HTMLElement | undefined>(undefined);
  const [enableAnimation, setEnableAnimation] = useState(false);
  const moreBtnRef = useRef<HTMLDivElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const tabLineRef = useRef<HTMLDivElement>(null);
  const primaryTabRefs = useRef<HTMLDivElement[]>([]);
  const secondaryTabRefs = useRef<HTMLDivElement[]>([]);

  const resetStyle = () => {
    containerRef.current?.classList.remove(styles.overflow);
    moreBtnRef.current?.classList.remove(styles.hidden);
    tabLineRef.current?.classList.remove(styles.hidden);
    primaryTabRefs.current.forEach((contentTabRef) => {
      contentTabRef.classList.remove(styles.hidden);
    });
    secondaryTabRefs.current.forEach((contentTabRef) => {
      contentTabRef.classList.remove(styles.hidden);
    });
  };

  const toggleTabs = (_tabIndex = tabIndex) => {
    resetStyle();
    const hiddenItems: Set<number> = new Set();
    const containerRefWidth = containerRef.current?.offsetWidth || 0;
    const buttonWidth = moreBtnRef.current?.offsetWidth || 0;
    let availableWidth = containerRefWidth - buttonWidth;

    if (alwaysShowActiveTab && primaryTabRefs.current[_tabIndex]) {
      const activeTab = primaryTabRefs.current[_tabIndex];
      activeTab.classList.remove(styles.hidden);
      activeTab.classList.add(styles.active);
      availableWidth -= activeTab.offsetWidth;
    }

    // hide the tabs that dont fit in the available width
    primaryTabRefs.current.forEach((tabRef, index) => {
      if (index !== _tabIndex || !alwaysShowActiveTab) {
        availableWidth -= tabRef.offsetWidth;
        if (availableWidth < buttonWidth && !tabRef.classList.contains(styles.hidden)) {
          tabRef.classList.add(styles.hidden);
          hiddenItems.add(index);
        }
      }
    });

    moreBtnRef.current?.classList.toggle(styles.hidden, hiddenItems.size === 0);
    secondaryTabRefs.current.forEach((tabRef, index) => {
      tabRef.classList.toggle(styles.hidden, !hiddenItems.has(index));
      if (alwaysShowActiveTab) {
        tabRef.classList.remove(styles.active);
      }
    });


    const visibleTabs = primaryTabRefs.current.filter((_, index) => !hiddenItems.has(index));
    const hasTabIndexDivergedFromRealIndex = !visibleTabs[tabIndex];
    if (hasTabIndexDivergedFromRealIndex) {
      setSelectedTab(primaryTabRefs.current[_tabIndex]);
    }
  };

  useEffect(() => {
    const handleResize = () => {
      toggleTabs();
    };
    const resizeObserver = new ResizeObserver(handleResize);

    if (containerRef.current) {
      resizeObserver.observe(containerRef.current);
    }

    setTimeout(() => {
      setEnableAnimation(true);
    }, 100);

    toggleTabs();

    return () => {
      resizeObserver.disconnect();
    };
  }, [tabIndex]);

  useEffect(() => {
    if (enableAnimation) {
      setSelectedTab(primaryTabRefs.current[tabIndex]);
      toggleTabs();
    }
  }, [enableAnimation])

  const onTabSelect = (index: number) => {
    onSelect && onSelect(index);
    setTabIndex(index);
    setSelectedTab(primaryTabRefs.current[index]);
    // remove active class from all other tabs
    primaryTabRefs.current.forEach((tabRef, i) => {
      if (i !== index) {
        tabRef.classList.remove(styles.active);
      }
      primaryTabRefs.current[index].classList.add(styles.active);
    });
    toggleTabs(index);
  };

  useEffect(() => {
    if (defaultActiveIndex !== tabIndex) {
      setTabIndex(defaultActiveIndex);
      setSelectedTab(primaryTabRefs.current[defaultActiveIndex]);
      toggleTabs(defaultActiveIndex);
    }
  }, [defaultActiveIndex]);

  const getTabStyle = () => {
    switch (priority) {
      case 'none':
        return null;
      case 'line':
        return (
          <TabLine
            borderPosition={borderPosition}
            selectedTab={selectedTab}
            enableAnimation={enableAnimation}
            className={tabClassName}
            ref={tabLineRef}
          />
        );
      case 'folder':
        return (
          <TabFolder
            selectedTab={selectedTab}
            enableAnimation={enableAnimation}
            className={tabClassName}
            ref={tabLineRef}
          />
        );
      case 'inner':
        return (
          <TabInner
            selectedTab={selectedTab}
            enableAnimation={enableAnimation}
            className={tabClassName}
            ref={tabLineRef}
          />
        );
      default:
        return (
          <TabLine
            borderPosition={borderPosition}
            selectedTab={selectedTab}
            enableAnimation={enableAnimation}
            className={tabClassName}
            ref={tabLineRef}
          />
        );
    }
  };

  return (
    <nav {...rest} className={classNames(styles.navTabs, styles.overflow, navClassName)} ref={containerRef}>
      {tabs
        .map((tab, index) => {
          // eslint-disable-next-line @typescript-eslint/no-unused-vars
          const { component, tabProps, ...tabRest } = tab;
          const showTabLine = priority === 'line' && enableAnimation;
          return (
            <div
              {...tabRest}
              className={classNames(
                styles.tab,
                // isActive && styles.active,
                !enableAnimation && styles.noAnimation,
                tab.className
              )}
              data-priority={priority}
              onClick={() => onTabSelect(index)}
              key={`tab-${index}`}
              ref={(ref) => ref && (primaryTabRefs.current[index] = ref)}
            >
              <tab.component menuItemProps={tabProps?.menuItemProps} isInMenu={false} />
              <TabLine borderPosition={borderPosition} className={classNames(styles.lineStyle, showTabLine && styles.visible)} />
            </div>
          );
        })}
      {!alwaysShowActiveTab && getTabStyle()}
      <div className={classNames(styles.more, styles.hidden)} ref={moreBtnRef}>
        <Dropdown
          placeholderContent={
            <div className={classNames(styles.dots)} data-priority="menu">
              <img src="https://static.bit.dev/bit-icons/more-h.svg" />
            </div>
          }
          dropClass={classNames(styles.secondaryTabContainer, secondaryNavClassName)}
          position={dropdownPosition}
          clickToggles
          margin={8}
        >
          {tabs
            .map((tab, index) => {
              // eslint-disable-next-line @typescript-eslint/no-unused-vars
              const { component, tabProps, ...tabRest } = tab;
              const isActive = index === tabIndex;
              return (
                <div
                  {...tabRest}
                  key={`dropdown-${index}`}
                  ref={(ref) => ref && (secondaryTabRefs.current[index] = ref)}
                  className={classNames(styles.item, tab.className)}
                >
                  <MenuItem
                    className={classNames(styles.menuItem)}
                    active={isActive}
                    onClick={() => onTabSelect(index)}
                  >
                    <tab.component menuItemProps={tabProps?.menuItemProps} isInMenu={true} />
                  </MenuItem>
                </div>
              );
            })}
        </Dropdown>
      </div>
      {children}
    </nav>
  );
}